def enrich(blocks: list[Block]) -> list[Block]:
    blocks = _split_fused(blocks)
    for row_index, row in enumerate(group_rows(blocks)):
        # A lone block on a line is prose, not a cell.
        if len(row) < 2:
            continue
        for col_index, block in enumerate(row):
            block.role = "table_cell"
            block.row = row_index
            block.col = col_index
    return blocks

def find_identifiers(text: str, config_dir: str | None = None) -> IdentifierCandidates:
    anchors = load_config("anchors", config_dir)
    cleaned = _clean_for_ids(text)
    normalized = normalize(text)
    out = IdentifierCandidates()

    for match in ISIN_ANCHORED.finditer(cleaned):
        out.isin.append(Candidate(value=match.group(1), anchored=True))
    seen = {c.value for c in out.isin}
    for match in ISIN_STRUCTURAL.finditer(cleaned):
        if match.group(1) not in seen:
            out.isin.append(Candidate(value=match.group(1)))

    # Layer 2 — label anchors. Best-effort: a hit raises confidence, an absence
    # is not a failure, because layer 1 already swept the whole page.
    ticker_anchor_present = any(
        anchor in normalized for anchor in (anchors.get("ticker") or [])
    )
    for match in TICKER_STRUCTURAL.finditer(cleaned):
        value = match.group(1)
        if value[:4] in TICKER_STOPWORDS:
            continue
        out.ticker.append(Candidate(value=value, anchored=ticker_anchor_present))

    for match in CNPJ_STRUCTURAL.finditer(cleaned):
        out.cnpj.append(Candidate(value=_format_cnpj(match.group(1)), anchored=True))

    return out

def locate(
    evidence: str, blocks: list[Block], value: str | None = None
) -> tuple[Block | None, float]:
    if not evidence or not evidence.strip():
        return None, 0.0

    target, squashed = normalize(evidence), _squash(evidence)
    if not squashed:
        return None, 0.0
    wanted = _squash(value) if value else ""

    best: tuple[Block | None, float] = (None, 0.0)
    for block in blocks:
        block_norm = normalize(block.text)
        if target and target in block_norm:
            return block, 1.0
        block_squashed = _squash(block.text)
        if squashed and block_squashed and squashed in block_squashed:
            if 0.85 > best[1]:
                best = (block, 0.85)
        elif block_squashed and squashed and block_squashed in squashed:
            # The value straddles several OCR lines; a partial anchor is still
            # a real anchor.
            score = 0.6 * (len(block_squashed) / len(squashed))
            if wanted and wanted in block_squashed:
                score = max(score, _HOLDS_VALUE)
            if score > best[1]:
                best = (block, score)
    return best

def _lookup(
    self,
    issuer: str | None = None,
    cnpj: str | None = None,
    isin: str | None = None,
    ticker: str | None = None,
    share_class: str | None = None,
) -> dict:
    keys = {"isin": isin, "ticker": ticker, "cnpj": cnpj, "issuer": issuer}
    matches: dict[str, int] = {}
    for key, value in keys.items():
        if not value:
            continue
        for index, row in enumerate(self.golden):
            if key == "issuer":
                if normalize(row["emissor"]) == normalize(value):
                    matches[key] = index
                    break
            elif normalize(row[_column(key)]) == normalize(value):
                matches[key] = index
                break

    if not matches:
        return {
            "status": "NOT_FOUND",
            "reason_code": ReasonCode.ISSUER_NOT_IN_GOLDEN.value,
            "message": "nenhum identificador do aviso consta na base de referência",
            "keys_tried": {k: v for k, v in keys.items() if v},
        }


